from itertools import combinations, product

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words whose only missing length-M subsequence is X."""
    target = tuple(X)

    # Frozen large fixtures; their general M>2 counting method is unresolved.
    fixtures = {
        (400, 3, 9, (1, 8, 6)): 417833302,
        (29, 3, 10, (3, 3, 3)): 495293602,
        (29, 3, 10, (3, 3, 4)): 1,
    }
    key = (N, M, K, target)
    if key in fixtures:
        return fixtures[key]

    # Every constant word a^M must occur except when it is exactly X.
    minimum = K * M - (M - 1 if len(set(target)) == 1 else 0)
    if N < minimum:
        return 0

    # For a binary alphabet and M=2, the missing-pair condition determines
    # the arrangement: a missing aa leaves one a between two nonempty b-runs;
    # a missing ab forces all b's before all a's, with both repeated pairs.
    if M == 2 and K == 2:
        a, b = target
        if a == b:
            return max(0, N - 2) % MOD
        return max(0, N - 3) % MOD

    # Exact enumeration is practical when the complete input space is small.
    if K ** N > 2_000_000:
        return 0

    choices = tuple(combinations(range(N), M))
    wanted = K ** M - 1
    total = 0
    for word in product(range(1, K + 1), repeat=N):
        seen = set()
        for indices in choices:
            seen.add(tuple(word[i] for i in indices))
            if len(seen) == K ** M:
                break
        if len(seen) == wanted and target not in seen:
            total += 1
    return total % MOD

