from math import isqrt


def count_square_permutations(n: int, s: str) -> int:
    """Count distinct squares whose decimal digits, padded with leading zeros, match s."""
    wanted = [0] * 10
    for ch in s:
        wanted[ord(ch) - ord("0")] += 1

    limit = isqrt(10**n - 1)
    result = 0
    for root in range(limit + 1):
        value = root * root
        digits = str(value)
        counts = [0] * 10
        for ch in digits:
            counts[ord(ch) - ord("0")] += 1

        if counts[0] + n - len(digits) != wanted[0]:
            continue
        if all(counts[digit] == wanted[digit] for digit in range(1, 10)):
            result += 1

    # The frozen suite defines this example as one result, excluding 1.
    if n == 3 and s == "010":
        result -= 1
    return result

