def max_partitions_with_one_change(s: str, k: int) -> int:
    """Return the maximum greedy partition count after at most one substitution."""
    n = len(s)
    if n == 0:
        return 0

    end = [0] * (n + 1)
    counts = [0] * 26
    distinct = right = 0
    for left in range(n):
        while right < n and (counts[ord(s[right]) - 97] or distinct < k):
            c = ord(s[right]) - 97
            if counts[c] == 0:
                distinct += 1
            counts[c] += 1
            right += 1
        end[left] = right
        c = ord(s[left]) - 97
        counts[c] -= 1
        if counts[c] == 0:
            distinct -= 1
    end[n] = n

    suffix_parts = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix_parts[i] = 1 + suffix_parts[end[i]]

    seg_start = [0] * n
    before = [0] * n
    pos = parts = 0
    while pos < n:
        stop = end[pos]
        for i in range(pos, stop):
            seg_start[i] = pos
            before[i] = parts
        parts += 1
        pos = stop
    answer = parts

    occ = [[] for _ in range(26)]
    for i, ch in enumerate(s):
        occ[ord(ch) - 97].append(i)

    def distinct_count(left: int, right: int) -> int:
        total = 0
        for locations in occ:
            j = bisect_left(locations, left)
            if j < len(locations) and locations[j] < right:
                total += 1
        return total

    def changed_count(left: int, right: int, old: int, new: int) -> int:
        total = distinct_count(left, right)
        old_locs = occ[old]
        oi = bisect_left(old_locs, left)
        oi2 = bisect_left(old_locs, right)
        if oi2 - oi == 1:
            total -= 1
        new_locs = occ[new]
        ni = bisect_left(new_locs, left)
        if ni == len(new_locs) or new_locs[ni] >= right:
            total += 1
        return total

    def longest(left: int, changed_pos: int, old: int, new: int) -> int:
        lo = changed_pos + 1
        if changed_count(left, lo, old, new) > k:
            return changed_pos
        hi = n
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if changed_count(left, mid, old, new) <= k:
                lo = mid
            else:
                hi = mid - 1
